package ma.autocarnet;
import android.content.Context;
import android.graphics.*;
import java.io.*;
import java.util.*;
import org.json.*;

final class RoadReport {
 static String view(String v){switch(v){case "front":return "Avant";case "rear":return "Arrière";case "left":return "Côté gauche";case "right":return "Côté droit";case "frontLeft":return "Avant gauche";case "frontRight":return "Avant droit";case "rearLeft":return "Arrière gauche";case "rearRight":return "Arrière droit";default:return "Détail / document";}}
 static String status(String v){switch(v){case "paid":return "Payée";case "disputed":return "Réclamation";case "closed":return "Dossier clos";default:return "À suivre";}}
 static JSONObject find(JSONArray a,String id)throws Exception {if(a!=null)for(int i=0;i<a.length();i++)if(id.equals(a.getJSONObject(i).optString("id")))return a.getJSONObject(i);return null;}
 static double refunds(JSONObject data,String period)throws Exception{double sum=0;JSONArray cases=data.optJSONArray("roadCases");if(cases!=null)for(int i=0;i<cases.length();i++){JSONArray a=cases.getJSONObject(i).getJSONArray("refunds");for(int j=0;j<a.length();j++){JSONObject r=a.getJSONObject(j);if(r.getString("date").startsWith(period))sum+=r.getDouble("amount");}}return sum;}
 static void finance(ReportPdf.Layout pdf,JSONObject data,String period,double paid)throws Exception{double received=refunds(data,period);pdf.heading("Remboursements et sortie nette");pdf.row("Remboursements réellement reçus dans la période",ReportPdf.num(received)+" DH");pdf.row("Sortie nette : paiements moins remboursements reçus",ReportPdf.num(paid-received)+" DH");pdf.paragraph("Les montants demandés, non payés ou attendus sont exclus. Le coût réparti reste une estimation des dépenses brutes et n’est pas un total net.",4);JSONArray cases=data.optJSONArray("roadCases");if(cases!=null)for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i);JSONArray a=c.getJSONArray("refunds");for(int j=0;j<a.length();j++){JSONObject r=a.getJSONObject(j);if(r.getString("date").startsWith(period))pdf.paragraph(r.getString("date")+" · "+c.getString("title")+" · reçu "+ReportPdf.num(r.getDouble("amount"))+" DH · "+r.optString("note"),12);}}}
 static void collect(JSONArray a,String label,Map<String,String> photos)throws Exception {if(a==null)return;for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);if(p.getString("id").endsWith(".jpg"))photos.put(p.getString("id"),label+" · vue : "+view(p.optString("view"))+" · ajout fichier : "+p.optString("addedAt"));}}
 static void write(Context c,JSONObject data,JSONObject options,OutputStream out)throws Exception{
  String caseId=options.optString("caseId");JSONObject item=caseId.isEmpty()?null:find(data.optJSONArray("roadCases"),caseId);if(!caseId.isEmpty()&&item==null)throw new IOException("Dossier absent");
  JSONArray selected=options.optJSONArray("sessionIds");if(selected==null)selected=new JSONArray();if(selected.length()>2)throw new IOException("Deux séances maximum par export");
  List<JSONObject> sessions=new ArrayList<>();for(int i=0;i<selected.length();i++){String id=selected.getString(i);if(item!=null&&!id.equals(item.optString("beforeId"))&&!id.equals(item.optString("afterId")))throw new IOException("Séance non liée au dossier");JSONObject s=find(data.optJSONArray("conditionSessions"),id);if(s==null)throw new IOException("Séance absente");sessions.add(s);}
  if(item==null&&sessions.isEmpty())throw new IOException("Sélection vide");
  Map<String,String> photos=new LinkedHashMap<>();boolean notes=options.optBoolean("notes"),costs=options.optBoolean("costs"),includePhotos=options.optBoolean("photos");
  try(ReportPdf.Layout pdf=new ReportPdf.Layout("DOSSIER & ÉTAT",item==null?"État photographié":item.getString("title"),data.getJSONObject("vehicle").optString("name"))){
   pdf.paragraph("Export du "+ReportPdf.today()+". Dates de prise de vue déclarées par le propriétaire, distinctes de l’ajout dans l’application. Cet historique n’est pas un horodatage certifié et n’établit pas la cause ni l’auteur d’un dommage.",8);
   if(item!=null){pdf.heading(item.getString("title"));pdf.paragraph("Date de la contravention, intervention ou découverte : "+item.getString("date")+" · état : "+status(item.getString("status")),4);pdf.paragraph("Lieu : "+item.optString("location")+" · contact : "+item.optString("contact")+" · référence : "+item.optString("reference"),10);pdf.paragraph("Dernière date sans ce dommage : "+item.optString("lastSeen")+" · échéance saisie : "+item.optString("due")+" · zone : "+view(item.optString("area")),4);pdf.paragraph("Dossier ajouté : "+item.getString("createdAt")+" · modifié : "+item.getString("updatedAt"),4);if(notes)pdf.paragraph(item.optString("note"),200);
    if(costs){Set<String> ids=ResalePdf.ids(item.optJSONArray("entryIds"));double paid=0,received=0;pdf.heading("Paiements liés (déjà comptés dans le journal)");for(JSONObject e:ReportPdf.entries(data))if(ids.contains(e.getString("id"))){paid+=e.getDouble("cost");pdf.paragraph(e.getString("date")+" · "+ReportPdf.num(e.getDouble("cost"))+" DH · "+e.optString("note"),20);if(includePhotos)collect(e.optJSONArray("photos"),"Paiement du "+e.getString("date"),photos);}JSONArray refunds=item.getJSONArray("refunds");for(int i=0;i<refunds.length();i++){JSONObject r=refunds.getJSONObject(i);received+=r.getDouble("amount");pdf.paragraph("Remboursement reçu : "+r.getString("date")+" · "+ReportPdf.num(r.getDouble("amount"))+" DH · "+r.optString("note"),20);}pdf.row("Total payé",ReportPdf.num(paid)+" DH");pdf.row("Total reçu",ReportPdf.num(received)+" DH");pdf.row("Coût net",ReportPdf.num(paid-received)+" DH");if(!item.isNull("amountDue"))pdf.row("Montant demandé encore non payé",ReportPdf.num(Math.max(0,item.getDouble("amountDue")-paid))+" DH");if(!item.isNull("expectedRefund"))pdf.row("Remboursement encore attendu (hors bilan)",ReportPdf.num(item.getDouble("expectedRefund"))+" DH");}
    if(includePhotos)collect(item.getJSONArray("photos"),"Dossier : "+item.getString("title"),photos);
   }
   if(includePhotos)for(JSONObject s:sessions){pdf.heading("Séance photographique");pdf.paragraph("Prise de vue déclarée : "+s.getString("capturedDate")+" · enregistrée dans l’application : "+s.getString("addedAt"),4);pdf.paragraph("Lieu : "+s.optString("location")+" · compteur annoté : "+(s.isNull("km")?"non renseigné":String.valueOf(s.getLong("km"))+" km"),4);if(notes)pdf.paragraph(s.optString("note"),200);collect(s.getJSONArray("photos"),"Prise déclarée : "+s.getString("capturedDate")+" · séance ajoutée : "+s.getString("addedAt"),photos);}
   if(photos.size()>120)throw new IOException("Trop de photos, exportez les séances séparément");
   for(Map.Entry<String,String> p:photos.entrySet()){File f=Store.photo(c,p.getKey());BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(o.outWidth<=0||o.outHeight<=0)throw new IOException("Photo absente ou illisible");o.inJustDecodeBounds=false;o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>1800)o.inSampleSize*=2;Bitmap b=BitmapFactory.decodeFile(f.getAbsolutePath(),o);if(b==null)throw new IOException("Photo illisible");try{pdf.newPage();pdf.heading("Photo conservée");pdf.paragraph(p.getValue(),10);float scale=Math.min(519f/b.getWidth(),(770-pdf.y)/b.getHeight()),w=b.getWidth()*scale,h=b.getHeight()*scale;pdf.canvas.drawBitmap(b,null,new RectF(38+(519-w)/2,pdf.y,38+(519+w)/2,pdf.y+h),pdf.paint);pdf.y+=h;}finally{b.recycle();}}
   pdf.finish();pdf.doc.writeTo(out);
  }
 }
}
